package com.udhaardaar.mvp

import android.app.AlertDialog
import android.content.Intent
import android.graphics.Color
import android.graphics.Rect
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.view.WindowManager
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

/** V5 shell: one home, domain-specific workflows, private vault and claim/legal centre. */
class V5HomeActivity : AppCompatActivity() {
    private val prefs by lazy { getSharedPreferences("udhaardaar_accounts", MODE_PRIVATE) }
    private val bg=Color.rgb(238,248,253);private val blue=Color.rgb(25,111,220);private val teal=Color.rgb(0,145,135);private val navy=Color.rgb(24,58,92);private val green=Color.rgb(25,145,78);private val amber=Color.rgb(210,135,15);private val red=Color.rgb(190,55,55)
    private var selectedDoc:Uri?=null
    private fun dp(x:Int)=(x*resources.displayMetrics.density).toInt()
    private fun card(c:Int=Color.WHITE,s:Int=Color.rgb(190,210,225))=GradientDrawable().apply{setColor(c);setStroke(dp(1),s);cornerRadius=dp(14).toFloat()}
    private fun tv(s:String,z:Float=15f,c:Int=navy)=TextView(this).apply{text=s;textSize=z;setTextColor(c);setPadding(dp(4),dp(3),dp(4),dp(3))}
    private fun ed(h:String)=EditText(this).apply{hint=h;textSize=14f;setSingleLine(true);setPadding(dp(10),dp(4),dp(10),dp(4));background=card();imeOptions=android.view.inputmethod.EditorInfo.IME_ACTION_NEXT;setOnFocusChangeListener{v,has->if(has)v.post{v.requestRectangleOnScreen(Rect(0,0,v.width,v.height),true)}}}
    private fun btn(s:String,c:Int,fn:()->Unit)=Button(this).apply{text=s;isAllCaps=false;textSize=13f;minHeight=0;minimumHeight=0;setPadding(dp(8),0,dp(8),0);setTextColor(Color.WHITE);background=card(c,c);setOnClickListener{fn()}}
    private fun root()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(8),dp(12),dp(14));setBackgroundColor(bg)}
    private fun put(r:LinearLayout,v:View,h:Int=44){r.addView(v,LinearLayout.LayoutParams(-1,dp(h)).apply{setMargins(0,dp(2),0,dp(2))})}
    private fun show(r:LinearLayout){val scroll=ScrollView(this).apply{isFillViewport=true;isSmoothScrollingEnabled=true;addView(r)};ViewCompat.setOnApplyWindowInsetsListener(scroll){v,insets->val ime=insets.getInsets(WindowInsetsCompat.Type.ime()).bottom;v.setPadding(v.paddingLeft,v.paddingTop,v.paddingRight,ime);insets};setContentView(scroll);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE)}
    private fun header(r:LinearLayout,title:String,sub:String){val h=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(8),dp(5),dp(8),dp(5));background=card()};h.addView(tv("UDHAARDAAR V5",11f,teal));h.addView(tv(title,20f));h.addView(tv(sub,11f,Color.DKGRAY));r.addView(h);r.addView(Space(this),LinearLayout.LayoutParams(1,dp(5)))}
    override fun onCreate(b:Bundle?){super.onCreate(b);home()}
    override fun onBackPressed(){home()}
    private fun home(){if(!prefs.getBoolean("logged_in",false)){startActivity(Intent(this,LoginActivity::class.java));finish();return};val r=root();header(r,"Personal financial command centre","Credit • obligations • documents • assets • succession");val m=prefs.getString("current_mobile","")?:"";put(r,tv("Welcome, ${prefs.getString("name_$m","User")}",17f));section(r,"CREDIT & OBLIGATIONS",blue)
        tile(r,"₹","Credit Registration","Personal • business • trade • advance • given/received",blue){startActivity(Intent(this,V5CreditRegistrationActivity::class.java))}
        tile(r,"🏦","Formal Credit","Sanction letter + statement + loan-charge audit",navy){formalAudit()}
        tile(r,"⌂","Rental / Lease","Rent, deposit, escalation, lease & arrears",teal){rental()}
        tile(r,"✓","Repayment Centre","Due • overdue • partial repayment • evidence",green){startActivity(Intent(this,V5RepaymentActivity::class.java))}
        section(r,"DIGITAL DOCUMENTS",amber);tile(r,"▤","DPN + Guarantor Guarantee","Generate • OTP consent • version • audit",amber){documents()};tile(r,"▣","Document & Audit Vault","Documents, consent events and evidence history",amber){documents()}
        section(r,"ASSET VAULT",teal);tile(r,"₹","Financial Asset Vault","Deposits • insurance • investments • pensions",teal){asset(false)};tile(r,"◆","Non-Financial Asset Vault","Property • vehicles • jewellery • business interests",teal){asset(true)};tile(r,"♙","Nominee / Trusted Person","Controlled family access; private by default",navy){trusted()}
        section(r,"SUCCESSION & LEGAL",red);tile(r,"⌘","Inheritance & Claim Centre","Asset discovery • heir/nominee • claim status",red){claims()};tile(r,"⚖","Legal Assistance","Evidence bundles • recovery/claim support",red){legal()};tile(r,"▤","Notifications & Readiness","Maturity • renewal • due dates • claim tasks",green){readiness()}
        put(r,btn("MY PROFILE",teal){owner()},44);put(r,btn("LOGOUT",Color.rgb(90,110,125)){prefs.edit().putBoolean("logged_in",false).remove("current_mobile").apply();startActivity(Intent(this,LoginActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish()},44);show(r)}
    private fun section(r:LinearLayout,s:String,c:Int){r.addView(tv(s,11f,c))}
    private fun tile(r:LinearLayout,icon:String,title:String,sub:String,c:Int,fn:()->Unit){val x=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(8),dp(4),dp(6),dp(4));background=card();setOnClickListener{fn()}};x.addView(tv(icon,20f,c),LinearLayout.LayoutParams(dp(36),dp(42)));val z=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutParams=LinearLayout.LayoutParams(0,-2,1f)};z.addView(tv(title,15f));z.addView(tv(sub,10f,Color.DKGRAY));x.addView(z);x.addView(tv("›",23f,c));r.addView(x);r.addView(Space(this),LinearLayout.LayoutParams(1,dp(3)))}
    private fun page(title:String,sub:String)=root().also{header(it,title,sub)}
    private fun asset(nonFinancial:Boolean){val r=page(if(nonFinancial)"Non-Financial Asset Vault" else "Financial Asset Vault","Private by default • link documents and nominees");val cat=Spinner(this);cat.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,(if(nonFinancial)listOf("Property / Land","House / Building","Vehicle","Jewellery / Valuables","Business Interest","Other") else listOf("Bank / Deposit","Insurance","Shares / Securities","Mutual Fund / Bond","Pension / Retirement","Loan Receivable","Other Investment")));val title=ed("Asset title / institution *");val ref=ed("Account / policy / registration reference");val value=ed("Approximate value");val owner=ed("Owner / co-owner");val nom=ed("Nominee / beneficiary");val maturity=ed("Maturity / renewal date");listOf(title,ref,value,owner,nom,maturity).forEach{put(r,it)};put(r,cat,42);put(r,btn("UPLOAD ASSET PROOF",teal){pickDocument()},44);put(r,btn("SAVE ASSET",green){if(title.text.toString().trim().length<2){toast("Enter asset title");return@btn};toast("Asset saved to private vault")},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun trusted(){val r=page("Nominee / Trusted Person","Controlled access — no automatic transfer of ownership");listOf("Trusted person name","Relationship","Mobile number","Permission level: Emergency discovery / View / Claim preparation").forEach{put(r,ed(it))};put(r,btn("SAVE TRUSTED PERSON",green){toast("Trusted-person permission saved")},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun claims(){val r=page("Inheritance & Claim Centre","Identify assets and prepare claims after a succession event");put(r,tv("Workflow: Owner → evidence → assets → nominee/heir → institution checklist → claim → closure",12f));val owner=ed("Owner / deceased person");val claimant=ed("Claimant / legal heir");val rel=ed("Relationship");val death=ed("Death / succession date");val inst=ed("Institution / authority");val status=Spinner(this);status.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Identified","Documents pending","Application prepared","Submitted","Query received","Approved","Transferred / closed","Disputed"));listOf(owner,claimant,rel,death,inst).forEach{put(r,it)};put(r,status,42);put(r,btn("UPLOAD DEATH / HEIR DOCUMENT",red){pickDocument()},44);put(r,btn("CREATE CLAIM FILE",green){toast("Claim file created with checklist and audit trail")},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun legal(){val r=page("Legal Assistance","Software-assisted evidence and professional referral");val issue=Spinner(this);issue.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Credit recovery / default","Asset inheritance claim","Succession / legal-heir documents","Document / transaction dispute"));val state=ed("City / State");put(r,issue,42);put(r,state);put(r,tv("Evidence: DPN, guarantee, consent log, repayment history, loan audit, asset proof and claim documents.",12f));put(r,btn("PREPARE EVIDENCE BUNDLE",amber){toast("Evidence bundle checklist prepared")},44);put(r,btn("FIND PROFESSIONAL ASSISTANCE",navy){toast("Professional referral layer ready")},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun documents(){val r=page("Digital Documents & Consent","Versioned evidence for future audit");val type=Spinner(this);type.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Demand Promissory Note","Guarantor Guarantee","Sanction Letter","Account Statement","Trade Invoice","Lease Agreement","Repayment Receipt","Asset Proof","Legal Claim"));put(r,type,42);put(r,btn("UPLOAD DOCUMENT",teal){pickDocument()},44);put(r,tv("Lifecycle: Draft → Sent → Viewed → Consent pending → OTP verified → Completed → Archived",12f));put(r,btn("GENERATE DPN + GUARANTEE",blue){AlertDialog.Builder(this).setTitle("Document templates").setMessage("Generate DPN and guarantor guarantee from final credit terms, then obtain required OTP consent before registration.").setPositiveButton("OK",null).show()},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun formalAudit(){val r=page("Formal Credit & Loan Charge Audit","Sanctioned terms versus actual account-statement charges");put(r,tv("1. Upload sanction letter → extract sanctioned ROI/fees.\n2. Upload account statement → identify actual charges.\n3. Reconcile each parameter and show evidence + variance.",12f));put(r,btn("UPLOAD SANCTION LETTER",teal){pickDocument()},44);put(r,btn("UPLOAD ACCOUNT STATEMENT",navy){pickDocument()},44);put(r,btn("RUN CHARGE COMPARISON",green){AlertDialog.Builder(this).setTitle("Loan Cost Audit").setMessage("Comparison engine reports matches, variances, refunds and review-required items.").setPositiveButton("OK",null).show()},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun rental(){val r=page("Rental / Lease","Dedicated lease workflow — not personal credit");listOf("Tenant / counterparty","Property / premises","Landlord / owner","Monthly rent","Security deposit","Lease start YYYY-MM-DD","Lease end YYYY-MM-DD","Rent due day 1–31","Annual escalation %","Notice period days","Utilities / maintenance responsibility").forEach{put(r,ed(it))};put(r,btn("UPLOAD LEASE AGREEMENT",teal){pickDocument()},44);put(r,btn("SAVE LEASE + SCHEDULE",green){toast("Separate lease record and rent schedule saved")},44);put(r,btn("HOME",navy){home()},44);show(r)}
    private fun readiness(){val r=page("Notifications & Readiness","Upcoming obligations and succession preparation");listOf("Credit due / overdue reminders","Rental due / arrears","Insurance / investment maturity","Document expiry / renewal","Inheritance claim next actions").forEach{tile(r,"•",it,"Reminder rule",green){toast("Reminder settings opened")}};put(r,btn("HOME",navy){home()},44);show(r)}
    private fun owner(){val m=prefs.getString("current_mobile","")?:"";val r=page("My Profile","Account owner and privacy controls");r.addView(tv(prefs.getString("name_$m","User")?:"User",20f));r.addView(tv("Mobile: $m",14f));r.addView(tv("Private asset vault • controlled trusted-person access • audit history",12f));put(r,btn("HOME",navy){home()},44);show(r)}
    private fun pickDocument(){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{type="application/pdf";addCategory(Intent.CATEGORY_OPENABLE);addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)},7001)}
    override fun onActivityResult(req:Int,res:Int,data:Intent?){super.onActivityResult(req,res,data);if(req==7001&&res==RESULT_OK&&data?.data!=null){selectedDoc=data.data;toast("Document selected and ready for the current workflow")}}
    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()
}
